from pptx import Presentation
prs = Presentation('BMW_1502_Presentation.pptx')
print(f'Slides: {len(prs.slides)}')
# Count quantitative slides
quant = 0
for s in prs.slides:
    for shape in s.shapes:
        if shape.has_table:
            quant += 1
            break
print(f'Slides with tables (quantitative): {quant}')
# Check all required sections
sections = ['Title Slide', 'Introduction', 'Key Features', 'Design', 'Engine', 'Interior', 'Safety', 'Conclusion']
for i, s in enumerate(prs.slides):
    for shape in s.shapes:
        if shape.has_text_frame:
            for p in shape.text_frame.paragraphs:
                t = p.text.strip()
                for sec in sections:
                    if sec.lower() in t.lower() and len(t) < 60:
                        print(f'  Slide {i+1}: Found section \"{sec}\" -> \"{t[:80]}\"')
                        sections.remove(sec)
                        break
print(f'Remaining sections not found: {sections}')
